    clifton: { name: "Clifton Sea View Residences", city: "Karachi", area: "Block 2, Clifton", type: "Residential · Serviced apartments", pic: "apt3", gal: ["apt3", "living1", "living2", "roof2", "apt2"], yield: 7.1, unit: 980, nav: 1012, raised: 41, target: 60, occ: 91, investors: 862, state: "open", days: 21, sqft: "96,500", floors: 14, tenants: 112, wault: "1.2 yrs", built: 2021, shariah: true, token: "CSV", tag: "Sea-facing rental homes" },
