  /* ---------- shared pieces ---------- */
  const sb = () => `<div class="sb"><span>9:41</span><div class="isl"></div><div class="rt"><i style="height:5px"></i><i style="height:8px"></i><i style="height:11px"></i><div class="bat"><b></b></div></div></div>`;
  const top = (title, back = "back", right = "") => `<div class="top">${back ? `<button class="ib" data-go="${back}">${ic("back")}</button>` : ""}<div class="ttl" style="flex:1;${back ? "text-align:center" : ""}">${title}</div>${right || (back ? '<div style="width:40px"></div>' : "")}</div>`;
