  const holdRow = (h) => { const p = P[h.id]; const ch = ((p.nav - h.cost) / h.cost) * 100; return `<div class="card hold" data-go="holding" data-a="prop:${h.id}">${ph(p.pic, "clean")}<div style="flex:1;min-width:0"><div class="b" style="font-size:14px">${p.name}</div><div class="sm muted">${p.city} · ${fmt(h.units)} units</div></div><div style="text-align:right"><div class="num" style="font-size:14.5px">${rs(holdVal(h))}</div><div class="sm ${ch >= 0 ? "up" : "down"}">${ch >= 0 ? "+" : ""}${ch.toFixed(1)}%</div></div></div>`; };
  const cur = () => P[st.prop];

